{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6B8E6D;--muted:#6b7280;--bg:#f7faf6;--card:#ffffff;--glass:rgba(255,255,255,0.6);--hero:#eaf3ec}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0f172a;margin:0;background:linear-gradient(180deg,var(--bg),#ffffff);min-height:100vh}
    header{background:linear-gradient(90deg, #ffffff 0%, rgba(234,243,236,0.6) 100%);backdrop-filter: blur(6px);border-bottom:1px solid #e6f0ea}
    .container{max-width:1100px;margin:0 auto;padding:28px}
    nav{display:flex;gap:16px;align-items:center;justify-content:space-between}
    .brand{font-weight:700;color:var(--accent)}
    .menu{display:flex;gap:12px}
    .menu a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    .menu a.cta{background:var(--accent);color:#fff}
    main{padding:36px 16px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .hero-card{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(16,24,40,0.06)}
    .small{font-size:14px;color:var(--muted)}
    h1{margin:0 0 8px;font-size:28px;color:#082222}
    p.lead{margin:0 0 16px;color:#334155}
    .switch{display:flex;align-items:center;gap:12px;padding:12px;background:linear-gradient(180deg,#fff,#fbfefb);border-radius:12px}
    .toggle{width:56px;height:28px;background:#d1e7da;border-radius:999px;position:relative;cursor:pointer}
    .knob{width:24px;height:24px;border-radius:50%;background:#fff;position:absolute;top:2px;left:2px;box-shadow:0 2px 6px rgba(2,6,23,0.12);transition:all 280ms cubic-bezier(.2,.9,.3,1)}
    .toggle.off{background:#e6e8eb}
    .toggle.off .knob{left:30px}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .plan{padding:18px;border-radius:12px;background:linear-gradient(180deg,var(--card),var(--glass));border:1px solid #eef6ee}
    .price{font-size:22px;font-weight:700;color:#06281e}
    .muted{color:var(--muted);font-size:13px}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#f0fbef;color:#0b5135;font-weight:600;font-size:13px}
    .cta-row{display:flex;gap:8px;margin-top:14px}
    button.primary{background:var(--accent);color:#fff;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    button.ghost{background:transparent;border:1px solid #dbeede;padding:10px 12px;border-radius:8px;cursor:pointer}
    footer{padding:28px;border-top:1px solid #eef5ee;margin-top:36px}
    /* Mood card */
    .mood-wrap{margin-top:16px;padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfffb);border:1px solid #eaf3ec}
    .moods{display:flex;gap:8px;flex-wrap:wrap}
    .mood{padding:10px 12px;border-radius:10px;background:#fff;border:1px solid #eef6ee;cursor:pointer;font-weight:600}
    .mood.active{background:var(--accent);color:#fff}
    /* responsive */
    @media (max-width:900px){.hero{grid-template-columns:1fr;}.plans{grid-template-columns:1fr}}  
  </style>
</head>
<body>
  <header>
    <div class='container'>
      <nav>
        <div style='display:flex;gap:12px;align-items:center'>
          <div class='brand'>{{BUSINESS_NAME}}</div>
          <div class='small'>A modern integrative atelier</div>
        </div>
        <div class='menu'>
          <a href='index.html'>Home</a>
          <a href='services.html'>Offerings</a>
          <a href='conditions.html'>Ailments</a>
          <a href='approach.html'>Our Way</a>
          <a href='pricing.html' class='cta'>Investment</a>
          <a href='about.html'>About</a>
          <a href='book.html'>Book</a>
          <a href='contact.html'>Connect</a>
        </div>
      </nav>
    </div>
  </header>
  <main>
    <div class='container'>
      <div class='hero'>
        <div>
          <div class='hero-card'>
            <h1>Investment & Packages</h1>
            <p class='lead'>Practical integrative pathways priced for clarity — choose the cadence that fits your life. No cures promised; clear guidance offered.</p>
            <div class='switch' aria-hidden='false'>
              <div class='small'>Show pricing as</div>
              <div id='pricingToggle' class='toggle' role='switch' aria-checked='true' tabindex='0'>
                <div class='knob'></div>
              </div>
              <div class='small'>Monthly</div>
            </div>
            <div class='plans' id='plans'>
              <div class='plan' data-key='tune'>
                <div class='pill'>Pulse Tune</div>
                <div style='height:8px'></div>
                <div class='price' data-price>—</div>
                <div class='muted'>One focused consult + plan</div>
                <div class='cta-row'>
                  <button class='primary' data-cta>Start with Pulse</button>
                  <button class='ghost' onclick="location.href='contact.html'">Questions</button>
                </div>
              </div>
              <div class='plan' data-key='align'>
                <div class='pill'>Alignment Series</div>
                <div style='height:8px'></div>
                <div class='price' data-price>—</div>
                <div class='muted'>Monthly coaching + integrative supports</div>
                <div class='cta-row'>
                  <button class='primary' data-cta>Join Alignment</button>
                  <button class='ghost' onclick="location.href='services.html'">Details</button>
                </div>
              </div>
              <div class='plan' data-key='continuum'>
                <div class='pill'>Continuum Intensive</div>
                <div style='height:8px'></div>
                <div class='price' data-price>—</div>
                <div class='muted'>Deep, time-boxed program for layered change</div>
                <div class='cta-row'>
                  <button class='primary' data-cta>Explore Intensive</button>
                  <button class='ghost' onclick="location.href='about.html'">How it works</button>
                </div>
              </div>
            </div>
          </div>
          <div class='mood-wrap'>
            <div class='small'>Where are you most stuck today?</div>
            <div class='moods' id='moods'>
              <div class='mood' data-mood='overwhelmed'>Overwhelmed</div>
              <div class='mood' data-mood='stuck'>Stuck in patterns</div>
              <div class='mood' data-mood='searching'>Exploring causes</div>
              <div class='mood' data-mood='steady'>Maintaining progress</div>
            </div>
            <div id='moodRecommendation' style='margin-top:12px'></div>
          </div>
        </div>
        <aside>
          <div class='hero-card'>
            <div class='small'>Quick comparator</div>
            <h2 style='margin-top:6px'>Monthly vs Package</h2>
            <p class='small'>Toggle to see how the same care looks when paid monthly or as a condensed package.</p>
            <div style='height:12px'></div>
            <dl>
              <dt class='small'>Pulse Tune</dt>
              <dd><strong id='p-tune'>—</strong><span class='muted'> / selected</span></dd>
              <dt class='small'>Alignment Series</dt>
              <dd><strong id='p-align'>—</strong></dd>
              <dt class='small'>Continuum Intensive</dt>
              <dd><strong id='p-cont'>—</strong></dd>
            </dl>
            <div style='height:12px'></div>
            <div class='small'>Have a custom rhythm in mind? <a href='contact.html'>Reach out</a> and we'll sketch options.</div>
          </div>
        </aside>
      </div>
    </div>
  </main>
  <footer>
    <div class='container'>
      <div style='display:flex;justify-content:space-between;align-items:center'>
        <div class='small'>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
        <div class='small'>Call <a href='tel:{{PHONE}}'>{{PHONE}}</a> • <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
      </div>
    </div>
  </footer>
  <script>
    (function(){
      // Pricing data (monthly and package)
      const data = {
        tune:{monthly:95,package:250},
        align:{monthly:295,package:750},
        continuum:{monthly:680,package:1800}
      };

      const toggle = document.getElementById('pricingToggle');
      const prices = document.querySelectorAll('[data-price]');
      const planEls = document.querySelectorAll('.plan');
      const summary = {tune:document.getElementById('p-tune'),align:document.getElementById('p-align'),continuum:document.getElementById('p-cont')};
      let mode = 'monthly';

      function format(n){return '$'+n.toLocaleString(undefined,{maximumFractionDigits:0})+(mode==='monthly'?'/mo':' total')}

      function animateNumber(el,from,to,duration=600){
        const start = performance.now();
        requestAnimationFrame(function step(ts){
          const t = Math.min(1,(ts-start)/duration);
          const val = Math.round(from + (to-from)*t);
          el.textContent = format(val);
          if(t<1) requestAnimationFrame(step);
        });
      }

      function render(){
        planEls.forEach(plan=>{
          const key = plan.getAttribute('data-key');
          const target = data[key][mode=== 'monthly' ? 'monthly' : 'package'];
          const priceEl = plan.querySelector('[data-price]');
          const current = parseInt(priceEl.getAttribute('data-current')||'0',10);
          animateNumber(priceEl,current,target);
          priceEl.setAttribute('data-current',target);
        });
        // summary
        animateNumber(summary.tune,parseInt(summary.tune.getAttribute('data-current')||'0',10),data.tune[mode==='monthly'?'monthly':'package']);
        summary.tune.setAttribute('data-current',data.tune[mode==='monthly'?'monthly':'package']);
        animateNumber(summary.align,parseInt(summary.align.getAttribute('data-current')||'0',10),data.align[mode==='monthly'?'monthly':'package']);
        summary.align.setAttribute('data-current',data.align[mode==='monthly'?'monthly':'package']);
        animateNumber(summary.continuum,parseInt(summary.continuum.getAttribute('data-current')||'0',10),data.continuum[mode==='monthly'?'monthly':'package']);
        summary.continuum.setAttribute('data-current',data.continuum[mode==='monthly'?'monthly':'package']);
      }

      // init set
      render();

      function setMode(m){mode=m;toggle.classList.toggle('off', m!=='monthly');toggle.setAttribute('aria-checked', m==='monthly');render();}

      toggle.addEventListener('click',function(){setMode(mode==='monthly'?'package':'monthly');});
      toggle.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' ') {e.preventDefault();setMode(mode==='monthly'?'package':'monthly');}});

      // Mood-to-Method
      const moods = document.getElementById('moods');
      const rec = document.getElementById('moodRecommendation');
      const moodMap = {
        overwhelmed:{title:'Pulse Tune recommended',desc:'A focused consult to clear immediate burdens and form a short plan.',cta:'Book a Tune',link:'book.html?program=tune'},
        stuck:{title:'Alignment Series suggested',desc:'A structured weekly rhythm to unravel patterns and practice alternatives.',cta:'Start Alignment',link:'book.html?program=align'},
        searching:{title:'Try a Continuum Deep-dive',desc:'A time-boxed intensive for layered exploration and synthesis.',cta:'Inquire about Intensive',link:'contact.html'},
        steady:{title:'Maintenance rhythm',desc:'Monthly check-ins and supports to sustain gains without overload.',cta:'Maintain Momentum',link:'book.html?program=align'}
      };

      moods.addEventListener('click',function(e){
        const t = e.target.closest('.mood');
        if(!t) return;
        [...moods.children].forEach(n=>n.classList.remove('active'));
        t.classList.add('active');
        const m = t.getAttribute('data-mood');
        const info = moodMap[m];
        rec.innerHTML = '<strong>'+info.title+'</strong><div class=small style="margin-top:6px">'+info.desc+'</div><div style="margin-top:10px"><a href="'+info.link+'" class="primary small-cta" style="background:var(--accent);color:#fff;padding:8px 10px;border-radius:8px;display:inline-block;text-decoration:none">'+info.cta+'</a></div>';
      });

    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6B8E6D;--muted:#6b7280;--bg:#f6fbf7}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:#082227}
    .wrap{max-width:1000px;margin:0 auto;padding:36px}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 0}
    .brand{font-weight:800;color:var(--accent)}
    nav a{margin-left:12px;color:#475569;text-decoration:none}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:20px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(12,18,24,0.06)}
    h1{margin:0 0 6px}
    .muted{color:var(--muted)}
    .method{padding:12px;border-radius:10px;background:#f9fff8;border:1px solid #eaf3ec;margin-top:12px}
    .mood-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .mood{padding:8px 10px;border-radius:8px;border:1px solid #e6f3e9;background:#fff;cursor:pointer}
    .mood.active{background:var(--accent);color:#fff}
    .cta{display:inline-block;margin-top:12px;padding:10px 12px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none}
    footer{margin-top:28px;padding-top:18px;border-top:1px solid #eef6ee;color:var(--muted)}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div>
        <div class='brand'>{{BUSINESS_NAME}}</div>
        <div class='muted'>Contemporary integrative care</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html'>Offerings</a>
        <a href='conditions.html'>Ailments</a>
        <a href='approach.html'>Our Way</a>
        <a href='pricing.html'>Investment</a>
        <a href='about.html'>About</a>
        <a href='book.html'>Book</a>
      </nav>
    </header>

    <main class='grid'>
      <section>
        <div class='card'>
          <h1>Who we are</h1>
          <p class='muted'>An integrative practice blending evidence, lived experience, and thoughtful rhythm-setting. We listen first, then design practical steps you can try between sessions.</p>

          <h3 style='margin-top:14px'>Our commitments</h3>
          <ul class='muted'>
            <li>No overpromises — education and skill-building first</li>
            <li>Individualized pacing and measurable checkpoints</li>
            <li>Collaborative records and referrals when helpful</li>
          </ul>

          <div class='method'>
            <strong>Our approach</strong>
            <div class='muted' style='margin-top:6px'>We blend short guided interventions with lifestyle framing to co-create pathways you can maintain. It’s practical, iterative, and tailored.</div>
          </div>

          <h3 style='margin-top:14px'>Programs rethought</h3>
          <p class='muted'>We frame care as rhythms: short pulses to clarify, series to re-pattern, and intensives when layered work is needed.</p>

        </div>

        <div style='height:16px'></div>

        <div class='card'>
          <h3>Meet the lead</h3>
          <p class='muted'>A clinician with broad training in whole-person care, emphasizing physiology, behavior, and contextual supports. Clinical decisions are collaborative and transparent.</p>

          <h4 style='margin-top:12px'>Clinical ethos</h4>
          <ol class='muted'>
            <li>Start with clarity: what matters most now?</li>
            <li>Design for your life’s rhythm</li>
            <li>Measure, adapt, and teach skills you keep</li>
          </ol>
        </div>
      </section>

      <aside>
        <div class='card'>
          <div class='muted'>Feeling this page — now what?</div>
          <div class='mood-row' id='moodBtns'>
            <div class='mood' data-key='curious'>Curious</div>
            <div class='mood' data-key='ready'>Ready to change</div>
            <div class='mood' data-key='overloaded'>Overloaded</div>
          </div>

          <div id='methodPreview' style='margin-top:12px'>
            <strong>Choose a state to see a suggested path</strong>
          </div>

          <a id='bookCta' class='cta' href='book.html'>Book a consult</a>

        </div>

        <div style='height:12px'></div>

        <div class='card'>
          <div class='muted'>Practicalities</div>
          <div style='margin-top:8px' class='muted'>Sessions by appointment. Insurance friendly documentation provided; some services are self-pay options.</div>
        </div>
      </aside>
    </main>

    <footer>
      <div class='muted'>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    (function(){
      const map = {
        curious:{title:'Start with a Pulse Tune',desc:'A single consult to orient, prioritize, and leave with a short plan.',cta:'Schedule a Pulse',href:'book.html?program=tune'},
        ready:{title:'Consider the Alignment Series',desc:'Week-to-week supports and practice windows for steady change.',cta:'Enroll in Alignment',href:'book.html?program=align'},
        overloaded:{title:'Begin with immediate relief',desc:'A Pulse Tune plus quick practical steps to reduce burden, then plan next moves.',cta:'Book Immediate Tune',href:'book.html?program=tune'}
      };

      const moodBtns = document.getElementById('moodBtns');
      const preview = document.getElementById('methodPreview');
      const bookCta = document.getElementById('bookCta');

      moodBtns.addEventListener('click',function(e){
        const btn = e.target.closest('.mood');
        if(!btn) return;
        [...moodBtns.children].forEach(n=>n.classList.remove('active'));
        btn.classList.add('active');
        const key = btn.getAttribute('data-key');
        const info = map[key];
        preview.innerHTML = '<strong>'+info.title+'</strong><div style="margin-top:8px" class="muted">'+info.desc+'</div>';
        bookCta.textContent = info.cta; bookCta.href = info.href;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6B8E6D;--muted:#6b7280}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:#f6fbf7;color:#082227}
    .wrap{max-width:900px;margin:0 auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:10px;color:#475569;text-decoration:none}
    .panel{background:#fff;padding:18px;border-radius:12px;box-shadow:0 12px 28px rgba(2,6,23,0.06);margin-top:16px}
    h1{margin:0}
    .form-row{display:flex;gap:8px;margin-top:12px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6f1ea}
    button{background:var(--accent);color:#fff;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    .muted{color:var(--muted)}
    .moods{display:flex;gap:8px;margin-top:12px}
    .mood{padding:8px 10px;border-radius:8px;border:1px solid #eef6ee;background:#fff;cursor:pointer}
    .mood.active{background:var(--accent);color:#fff}
    .suggestion{margin-top:12px;padding:12px;border-radius:8px;background:#f9fff8;border:1px solid #eaf3ec}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div>
        <div style='font-weight:800;color:var(--accent)'>{{BUSINESS_NAME}}</div>
        <div class='muted'>Book a time to begin</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html'>Offerings</a>
        <a href='pricing.html'>Investment</a>
        <a href='about.html'>About</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </header>

    <main>
      <div class='panel'>
        <h1>Reserve time</h1>
        <p class='muted'>Select a pathway and share a few details so we can tailor the first session. We’ll follow up to confirm availability.</p>

        <div style='margin-top:12px'>
          <label class='muted'>Choose a program</label>
          <select id='program'>
            <option value='tune'>Pulse Tune — single consult</option>
            <option value='align'>Alignment Series — monthly</option>
            <option value='continuum'>Continuum Intensive — deep program</option>
          </select>
        </div>

        <div style='margin-top:12px'>
          <label class='muted'>Your current state</label>
          <div class='moods' id='moodSelect'>
            <div class='mood' data-mood='anxious'>Anxious</div>
            <div class='mood' data-mood='tired'>Tired</div>
            <div class='mood' data-mood='curious'>Curious</div>
            <div class='mood' data-mood='sick'>Physically unwell</div>
          </div>
        </div>

        <div id='methodCard' class='suggestion'>
          Choose a state to see the suggested first steps and a tailored CTA.
        </div>

        <form id='booking' style='margin-top:12px'>
          <div class='form-row'>
            <input id='name' placeholder='Your full name' required>
            <input id='phone' placeholder='Phone (optional)'>
          </div>
          <div style='margin-top:8px'>
            <input id='email' type='email' placeholder='Email' required>
          </div>
          <div style='margin-top:8px'>
            <textarea id='notes' rows='4' placeholder='Briefly: what brought you here?'></textarea>
          </div>
          <div style='margin-top:12px;display:flex;gap:8px;align-items:center'>
            <button type='submit' id='submitBtn'>Request this slot</button>
            <div class='muted'>Or <a href='contact.html'>email us</a> for questions</div>
          </div>
        </form>
      </div>
    </main>

    <footer style='margin-top:18px' class='muted'>By submitting, you agree to receive scheduling communication. Medical disclaimers available on the Ailments page.</footer>
  </div>

  <script>
    (function(){
      const moodMap = {
        anxious:{title:'Gentle orientation',desc:'Begin with a Pulse Tune — short, focused session to calm immediate concerns and set 1–2 practical steps.',cta:'Request a Pulse Tune'},
        tired:{title:'Rhythm-friendly plan',desc:'Alignment Series often helps with energy patterns; we suggest a pacing conversation and small daytime experiments.',cta:'Ask about Alignment'},
        curious:{title:'Exploratory consult',desc:'A Pulse Tune or a longer intake depending on depth. Good for mapping possible directions.',cta:'Request an Exploratory Tune'},
        sick:{title:'Assess & coordinate care',desc:'We prioritize a clinical intake to ensure safety and coordinate any needed referrals.',cta:'Request a Clinical Intake'}
      };

      const moodSelect = document.getElementById('moodSelect');
      const methodCard = document.getElementById('methodCard');
      const programSelect = document.getElementById('program');
      const submitBtn = document.getElementById('submitBtn');

      function updateCtaText(){
        const program = programSelect.value;
        if(program==='tune') submitBtn.textContent = 'Request a Pulse Tune';
        else if(program==='align') submitBtn.textContent = 'Request Alignment Series';
        else submitBtn.textContent = 'Request Continuum Intensive';
      }

      programSelect.addEventListener('change',updateCtaText);
      updateCtaText();

      moodSelect.addEventListener('click',function(e){
        const btn = e.target.closest('.mood'); if(!btn) return;
        [...moodSelect.children].forEach(n=>n.classList.remove('active'));
        btn.classList.add('active');
        const key = btn.getAttribute('data-mood');
